"""Render paired stakeholder maps to offline HTML, SVG, JSON and CSV."""
import argparse,base64,csv,html,io,json,sys
from datetime import date
from pathlib import Path

LEVELS=('high','low','unknown');CONFIDENCE=('unknown','low','medium','high')
STANCES=('unknown','supportive','neutral','skeptical','opposed')
REPRESENTATION=('absent','proposed','confirmed');OWNERSHIP=('proposed','confirmed','unknown')
def esc(x):return html.escape(str(x),quote=True)
def _text(x,k,c,required=True):
 v=x.get(k)
 if not isinstance(v,str) or (required and not v.strip()):raise ValueError(f'{c} {k}: {"nonempty " if required else ""}text required')
def _date(v,c,nullable=False):
 if nullable and v=='':return
 try:
  if date.fromisoformat(v).isoformat()!=v:raise ValueError
 except (TypeError,ValueError):raise ValueError(f'{c}: ISO date YYYY-MM-DD required') from None
def pi_quadrant(s):
 if s['power']=='unknown' or s['interest']=='unknown':return 'unknown'
 return {('high','high'):'manage_closely',('high','low'):'keep_satisfied',('low','high'):'keep_informed',('low','low'):'monitor'}[(s['power'],s['interest'])]
def ip_quadrant(s):
 if s['power']=='unknown' or s['impact']=='unknown':return 'unknown'
 return {('low','high'):'q1_elevate_voice',('high','high'):'q2_impacted_empowered',('low','low'):'q3_monitor',('high','low'):'q4_gatekeeper'}[(s['power'],s['impact'])]
def validate(data):
 if not isinstance(data,dict):raise ValueError('Expected a stakeholder-map snapshot object')
 for k in ('title','version','as_of','source','scope','state','decision_boundary'):_text(data,k,'snapshot')
 _date(data['as_of'],'as_of')
 d=data.get('dimensions')
 if not isinstance(d,dict):raise ValueError('dimensions is required')
 for k in ('power_basis','interest_basis','impact_basis','placement_warning','authority_warning'):_text(d,k,'dimensions')
 rows=data.get('stakeholders')
 if not isinstance(rows,list) or not rows:raise ValueError('stakeholders must be a nonempty list')
 ids=set()
 for s in rows:
  if not isinstance(s,dict):raise ValueError('Each stakeholder must be an object')
  for k in ('id','name','role','scope','power','interest','impact','confidence','power_domain','evidence','evidence_ref','assessed_on','current_stance','engagement_strategy','representation_state','authority','owner','ownership_state','migration_target','migration_action','trigger','next_review','source','note'):_text(s,k,'stakeholder',required=k not in ('evidence_ref','assessed_on','next_review','note'))
  if s['id'] in ids:raise ValueError(f'duplicate stakeholder id: {s["id"]}')
  ids.add(s['id'])
  if s['power'] not in LEVELS or s['interest'] not in LEVELS or s['impact'] not in LEVELS or s['confidence'] not in CONFIDENCE or s['current_stance'] not in STANCES or s['representation_state'] not in REPRESENTATION or s['ownership_state'] not in OWNERSHIP:raise ValueError(f'{s["id"]}: invalid enumerated value')
  if s['assessed_on']:_date(s['assessed_on'],f'{s["id"]} assessed_on')
  if s['next_review']:_date(s['next_review'],f'{s["id"]} next_review')
  if s['representation_state']=='confirmed' and (not s['evidence_ref'] or not s['assessed_on']):raise ValueError(f'{s["id"]}: confirmed representation requires evidence reference and assessment date')
 events=data.get('events',[])
 if not isinstance(events,list):raise ValueError('events must be a list')
 for ev in events:
  for k in ('id','date','label','state','source'):_text(ev,k,'event')
  _date(ev['date'],f'{ev["id"]} date')
 p=data.get('presentation');a=data.get('analysis')
 if not isinstance(p,dict) or not isinstance(a,dict):raise ValueError('presentation and analysis are required')
 for k in ('eyebrow','headline','lede','default_stakeholder_id','decision'):_text(p,k,'presentation')
 if p['default_stakeholder_id'] not in ids:raise ValueError('default_stakeholder_id must reference stakeholders')
 for k in ('method','comparison_rule','voice_rule','authority_boundary','revisit_rule'):_text(a,k,'analysis')
 return data
def assessment(data,rows=None):
 rows=data['stakeholders'] if rows is None else rows;out={'q1':[],'manage_closely':[],'unknown':[],'underengaged':[],'unconfirmed_representation':[],'owner_gaps':[],'pi':{},'ip':{}}
 for s in rows:
  pi=pi_quadrant(s);ip=ip_quadrant(s);out['pi'][s['id']]=pi;out['ip'][s['id']]=ip
  if ip=='q1_elevate_voice':out['q1'].append(s['id'])
  if pi=='manage_closely':out['manage_closely'].append(s['id'])
  if pi=='unknown' or ip=='unknown':out['unknown'].append(s['id'])
  if ip=='q1_elevate_voice' and pi!='manage_closely':out['underengaged'].append(s['id'])
  if s['representation_state']!='confirmed':out['unconfirmed_representation'].append(s['id'])
  if s['ownership_state']!='confirmed':out['owner_gaps'].append(s['id'])
 return out
def safe(v):
 s='' if v is None else str(v)
 return "'"+s if isinstance(v,str) and s.startswith(('=','+','-','@','\t','\r')) else s
def render_csv(data):
 validate(data);s=io.StringIO(newline='');w=csv.writer(s,lineterminator='\n');w.writerow(['stakeholder_id','name','role','scope','power','interest','impact','power_interest_quadrant','impact_power_quadrant','confidence','power_domain','evidence','evidence_ref','assessed_on','current_stance','engagement_strategy','representation_state','authority','owner','ownership_state','migration_target','migration_action','trigger','next_review','source','note','as_of','decision_boundary'])
 for x in data['stakeholders']:w.writerow([safe(v) for v in [x['id'],x['name'],x['role'],x['scope'],x['power'],x['interest'],x['impact'],pi_quadrant(x),ip_quadrant(x),x['confidence'],x['power_domain'],x['evidence'],x['evidence_ref'],x['assessed_on'],x['current_stance'],x['engagement_strategy'],x['representation_state'],x['authority'],x['owner'],x['ownership_state'],x['migration_target'],x['migration_action'],x['trigger'],x['next_review'],x['source'],x['note'],data['as_of'],data['decision_boundary']]])
 return s.getvalue()
def txt(x,y,v,size=13,fill='#13294b',weight='400'):return f'<text x="{x}" y="{y}" font-family="Arial,sans-serif" font-size="{size}" fill="{fill}" font-weight="{weight}">{esc(v)}</text>'
def render_svg(data):
 validate(data);a=assessment(data);w=1440;h=max(900,590+max(len(data['stakeholders']),4)*38);out=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}" role="img" aria-labelledby="title desc">',f'<title id="title">{esc(data["title"])}</title>',f'<desc id="desc">Paired qualitative stakeholder maps as of {esc(data["as_of"])}. Unknown placements remain outside the grids.</desc>','<rect width="100%" height="100%" fill="#f4f7fb"/><rect width="12" height="100%" fill="#173b2d"/>',txt(38,42,data['presentation']['eyebrow'].upper(),12,'#d80b61','800'),txt(38,96,data['presentation']['headline'],40,'#0c234b','800'),txt(38,130,data['presentation']['lede'],15,'#536581')]
 metrics=[('Q1 ELEVATE',len(a['q1'])),('MANAGE CLOSELY',len(a['manage_closely'])),('UNKNOWN',len(a['unknown'])),('REPRESENTATION OPEN',len(a['unconfirmed_representation'])),('OWNER GAPS',len(a['owner_gaps']))]
 for i,(k,v) in enumerate(metrics):
  x=38+i*270;out += [f'<rect x="{x}" y="155" width="252" height="78" rx="14" fill="#fff" stroke="#ccd6e5"/>',txt(x+15,178,k,10,'#667085','800'),txt(x+15,211,str(v),22,'#0c234b','800')]
 labels_pi=[('keep_informed','Low power / high interest'),('manage_closely','High power / high interest'),('monitor','Low power / low interest'),('keep_satisfied','High power / low interest')]
 labels_ip=[('q1_elevate_voice','Q1 high impact / low power'),('q2_impacted_empowered','Q2 high impact / high power'),('q3_monitor','Q3 low impact / low power'),('q4_gatekeeper','Q4 low impact / high power')]
 def grid(x0,title,labels,key):
  parts=[txt(x0,278,title,18,'#0c234b','800')]
  for i,(code,label) in enumerate(labels):
   x=x0+(i%2)*330;y=300+(i//2)*170;members=[s for s in data['stakeholders'] if (pi_quadrant(s) if key=='pi' else ip_quadrant(s))==code]
   parts += [f'<rect x="{x}" y="{y}" width="315" height="155" rx="12" fill="#fff" stroke="#ccd6e5"/>',txt(x+12,y+24,label,11,'#536581','800')]
   for j,s in enumerate(members[:5]):parts.append(txt(x+14,y+50+j*20,s['id']+' - '+s['name'][:24],10,'#13294b','700'))
  return parts
 out += grid(38,'Power x Interest',labels_pi,'pi')+grid(752,'Impact x Power',labels_ip,'ip')
 unknown=[s for s in data['stakeholders'] if pi_quadrant(s)=='unknown' or ip_quadrant(s)=='unknown'];y=665;out += [txt(38,y,'UNKNOWN / UNPLACED',11,'#a25b00','800')]
 for s in unknown:out += [txt(200,y,s['id']+' - '+s['name']+' | power '+s['power']+', interest '+s['interest']+', impact '+s['impact'],10,'#536581','700')];y+=22
 out += [txt(38,h-55,'Placements are qualitative hypotheses; no within-quadrant ranking or measured coordinates are implied.',11,'#536581','800'),txt(38,h-32,data['analysis']['authority_boundary'][:180],10,'#667085'),'</svg>'];return ''.join(out)
def _json(x):return json.dumps(x,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
def uri(x,m):return 'data:'+m+';base64,'+base64.b64encode(x.encode()).decode()

