 rep={'__TITLE__':esc(data['title']),'__EYEBROW__':esc(data['presentation']['eyebrow']),'__HEADLINE__':esc(data['presentation']['headline']),'__LEDE__':esc(data['presentation']['lede']),'__LEVEL_OPTIONS__':opts(LEVELS),'__CONFIDENCE_OPTIONS__':opts(CONFIDENCE),'__STANCE_OPTIONS__':opts(STANCES),'__REPRESENTATION_OPTIONS__':opts(REPRESENTATION),'__OWNERSHIP_OPTIONS__':opts(OWNERSHIP),'__COMPARE__':esc(data['analysis']['comparison_rule']),'__VOICE__':esc(data['analysis']['voice_rule']),'__AUTH__':esc(data['analysis']['authority_boundary']),'__REVISIT__':esc(data['analysis']['revisit_rule']),'__DATA__':_json(data),'__CSV__':_json(csv_text),'__SVG__':_json(uri(svg,'image/svg+xml'))}
